from __future__ import annotations
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
obj=json.loads((ROOT/'course_graph.ru-draft.v1.5.json').read_text(encoding='utf-8'))
nodes=[{k:n[k] for k in ('id','title','section','source_quality','translation_status','full_text','full_text_ru','translation_notes','source_pages')} for n in obj['topics']]
safe=json.dumps(nodes,ensure_ascii=False).replace('</','<\\/')
html='''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>GIC — проверка перевода учебных текстов</title><style>
:root{color-scheme:light dark;font-family:system-ui,-apple-system,Arial,sans-serif}body{margin:0;background:#f6f8fb;color:#192536}header{padding:22px 32px;background:#fff;border-bottom:1px solid #d9e0e9}h1{margin:0 0 8px;font-size:24px}.muted{color:#6c7688;font-size:13px}.top{display:flex;gap:12px;align-items:center;margin-top:16px;flex-wrap:wrap}input,select{background:#fff;border:1px solid #b8c5d4;border-radius:9px;padding:11px;font-size:14px;color:#192536}input{min-width:270px;flex:1}.layout{display:grid;grid-template-columns:290px 1fr;min-height:calc(100vh - 140px)}aside{overflow-y:auto;max-height:calc(100vh - 140px);background:#fff;border-right:1px solid #d9e0e9;padding:12px}.topic{display:block;width:100%;border:0;border-radius:8px;background:transparent;text-align:left;padding:11px;margin-bottom:4px;cursor:pointer;color:inherit}.topic:hover,.topic.active{background:#eaf1fd}.topic b{font-size:13px}.topic .muted{margin-top:4px}.content{padding:20px 25px;min-width:0}.heading{display:flex;gap:10px;justify-content:space-between;flex-wrap:wrap}.badge{display:inline-block;background:#e3ecfb;color:#274b88;border-radius:20px;padding:5px 11px;font-size:12px;font-weight:600}.pending{background:#fff1dc;color:#885300}.notsource{background:#eee;color:#666}.cols{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin-top:18px}.panel{min-width:0;background:white;border:1px solid #d9e0e9;border-radius:12px;overflow:hidden}.panel-title{padding:12px 16px;border-bottom:1px solid #d9e0e9;font-size:14px;font-weight:700}.panel pre{padding:16px;white-space:pre-wrap;overflow-wrap:anywhere;font-family:system-ui,Arial,sans-serif;font-size:13px;line-height:1.5;margin:0;max-height:70vh;overflow:auto}.alert{padding:13px;border-left:3px solid #bc8a41;background:#fff9e9;margin-top:12px;font-size:13px}@media(max-width:980px){.layout{display:block}aside{max-height:190px}.cols{grid-template-columns:1fr}header{padding:16px}.content{padding:12px}}@media(prefers-color-scheme:dark){body{background:#111926;color:#edf2fb}header,aside,.panel,input,select{background:#1d2938;color:#edf2fb;border-color:#344456}.topic:hover,.topic.active{background:#2a3953}.muted{color:#9eadbf}.panel-title{border-color:#344456}.alert{background:#42361b}}
</style></head><body><header><h1>Переводы тем GIC — просмотр и проверка</h1><div class="muted">Переведены все 132 ноды с учебными материалами. Графические схемы и формулы из PDF могут требовать отдельной сверки.</div><div class="top"><input id="q" placeholder="Поиск по ID, названию, разделу..." aria-label="Поиск"><select id="filter"><option value="all">Все темы</option><option value="translated_from_extracted_text">Переведённые</option><option value="pending_translation">Не переведённые</option><option value="no_source">Без источника</option></select><b id="counter"></b></div></header><div class="layout"><aside id="list"></aside><main class="content"><div class="heading"><h2 id="name">Выберите тему</h2><span id="status" class="badge"></span></div><div class="muted" id="source"></div><div id="notes"></div><div class="cols"><section class="panel"><div class="panel-title">Русский текст</div><pre id="ru"></pre></section><section class="panel"><div class="panel-title">Английский оригинал</div><pre id="en"></pre></section></div></main></div><script>
const topics = __DATA__;
const $=id=>document.getElementById(id);
const statuses={translated_from_extracted_text:'Переведено по извлечённому тексту',pending_translation:'Перевод отсутствует',no_source:'Нет учебного источника',translated_draft_unreviewed:'Не проверен'};
let selected=null;
function show(topic){selected=topic.id;$('name').textContent=topic.id+' — '+topic.title;$('status').textContent=statuses[topic.translation_status];$('status').className='badge '+(topic.translation_status==='pending_translation'?'pending':topic.translation_status==='no_source'?'notsource':'');$('source').textContent='Раздел: '+topic.section+' · Качество источника: '+topic.source_quality+' · Страниц: '+topic.source_pages.length;$('ru').textContent=topic.full_text_ru||(topic.translation_status==='no_source'?'Учебный материал для этой темы не обнаружен.':'Русский перевод ещё не подготовлен.');$('en').textContent=topic.full_text||'Нет исходного учебного текста.';$('notes').replaceChildren();if(topic.translation_notes.length){let p=document.createElement('div');p.className='alert';p.textContent=topic.translation_notes.join(' ');$('notes').appendChild(p)}renderList()}
function renderList(){const query=$('q').value.trim().toLowerCase();const status=$('filter').value;const matching=topics.filter(t=>(status==='all'||t.translation_status===status)&&[t.id,t.title,t.section].join(' ').toLowerCase().includes(query));$('counter').textContent=matching.length+' из '+topics.length;const frag=document.createDocumentFragment();for(const t of matching){const el=document.createElement('button');el.className='topic'+(selected===t.id?' active':'');const b=document.createElement('b');b.textContent=t.id+' '+t.title;const p=document.createElement('div');p.className='muted';p.textContent=statuses[t.translation_status];el.append(b,p);el.onclick=()=>show(t);frag.append(el)}$('list').replaceChildren(frag)}
$('q').addEventListener('input',renderList);$('filter').addEventListener('change',renderList);renderList();show(topics.find(t=>t.translation_status==='translated_from_extracted_text')||topics[0]);
</script></body></html>'''.replace('__DATA__',safe)
(ROOT/'translation_viewer.html').write_text(html,encoding='utf-8')
print('HTML bytes',len(html.encode('utf-8')))
